  var ringCtx = ringCv.getContext('2d');
  var ripCtx = ripCv.getContext('2d');
  var CV = { key: '', S: 0, dpr: 1, RS: 0 };
  var COL = { start: rgbOf(QW.cStart), end: rgbOf(QW.cEnd), ring: rgbOf(QW.cRing), rip: blend(QW.cRing, QW.cHalo, 0.5) };
  var PASSES = 5;
  var breathOrigin = 0;
