    gold:      [mixRgb(orange, redOrange, 0.4), gold, goldLit],
    green:     [mixRgb(green, ever, 0.55), green, mixRgb(green, goldLit, 0.5)],
    evergreen: [scaleRgb(ever, 0.7), ever, mixRgb(ever, green, 0.35)]
