      a: -PI / 2 + (i - mid) * gap + (r() - 0.5) * gap * 0.25 * v,
      L: prof[Math.min(d, 4)] * (1 + (r() - 0.5) * 0.28 * v),
      w: gap * (0.78 + (r() - 0.5) * 0.2 * v)
