  ctx.lineWidth = 0.9;
  ctx.beginPath(); ctx.moveTo(knee[0] + 1.5, knee[1] + 0.5); ctx.lineTo(foot[0] + 1.5, foot[1]); ctx.stroke();
  // front and middle legs
  ctx.strokeStyle = '#3a2a20';
  ctx.lineWidth = 1;
