  ctx.fillStyle = '#2a1d16';
  ctx.beginPath(); ctx.arc(8.5, -6, 3, 0, TAU); ctx.fill();
  ctx.fillStyle = 'rgba(210,180,130,0.8)';
  ctx.beginPath(); ctx.arc(9.6, -6.8, 0.8, 0, TAU); ctx.fill();
