  if (idx === 1) { var ix = W * lerp(0.1, 0.16, r()); bx = left ? ix : W - ix; by = -sc * 0.12; a0 = lerp(0.85, 1.1, r()); }
  if (idx === 2) { by = WINT.branchTop + lerp(110, 170, r()); a0 = lerp(-0.1, 0.08, r()); }
